param(                                                                                                                                                                                                  
        [string]$Repo = "Yongbi21/Coding-Workflow",                                                                                                                                                         
        [string]$Branch = "main",                                                                                                                                                                           
        [switch]$Force                                                                                                                                                                                      
    )                                                                                                                                                                                                       
                                                                                                                                                                                                            
    $ErrorActionPreference = "Stop"                                                                                                                                                                         
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12                                                                                                                         
                                                                                                                                                                                                            
    $rootDir     = (Get-Location).ProviderPath                                                                                                                                                              
    $excludeDirs = @(".git", ".vs", "bin", "obj", "node_modules", "packages")                                                                                                                               
                                                                                                                                                                                                            
    $csprojFiles = @(                                                                                                                                                                                       
        Get-ChildItem -LiteralPath $rootDir -Filter "*.csproj" -File -ErrorAction SilentlyContinue                                                                                                          
        Get-ChildItem -LiteralPath $rootDir -Directory -ErrorAction SilentlyContinue |                                                                                                                      
            Where-Object { $_.Name -notin $excludeDirs } |                                                                                                                                                  
            ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -Filter "*.csproj" -File -ErrorAction SilentlyContinue }                                                                                
    )                                                                                                                                                                                                       
                                                                                                                                                                                                            
    $installBase    = $rootDir                                                                                                                                                                              
    $selectedCsproj = $null                                                                                                                                                                                 
                                                                                                                                                                                                            
    if ($csprojFiles.Count -gt 0) {                                                                                                                                                                         
        Write-Host "Where should docs\Coding-Workflow be installed?" -ForegroundColor Cyan                                                                                                                  
        Write-Host "  [1] Solution / Root level (default)"                                                                                                                                                  
        Write-Host "  [2] Project level (.csproj)"                                                                                                                                                          
        $choice = (Read-Host "Choose [1/2]").Trim()                                                                                                                                                         
                                                                                                                                                                                                            
        if ($choice -eq "2") {                                                                                                                                                                              
            if ($csprojFiles.Count -eq 1) {                                                                                                                                                                 
                $selectedCsproj = $csprojFiles[0]                                                                                                                                                           
            }                                                                                                                                                                                               
            else {                                                                                                                                                                                          
                Write-Host "Select target project:" -ForegroundColor Cyan                                                                                                                                   
                for ($i = 0; $i -lt $csprojFiles.Count; $i++) {                                                                                                                                             
                    Write-Host "  [$($i + 1)] $($csprojFiles[$i].Name)"                                                                                                                                     
                }                                                                                                                                                                                           
                $pickRaw = (Read-Host "Enter number (1-$($csprojFiles.Count))").Trim()                                                                                                                      
                $pickNum = 0                                                                                                                                                                                
                if (-not [int]::TryParse($pickRaw, [ref]$pickNum) -or $pickNum -lt 1 -or $pickNum -gt $csprojFiles.Count) {                                                                                 
                    Write-Error "Invalid project selection '$pickRaw'. Aborting."                                                                                                                           
                    return                                                                                                                                                                                  
                }                                                                                                                                                                                           
                $selectedCsproj = $csprojFiles[$pickNum - 1]                                                                                                                                                
            }                                                                                                                                                                                               
            $installBase = $selectedCsproj.DirectoryName                                                                                                                                                    
        }                                                                                                                                                                                                   
        elseif ($choice -ne "" -and $choice -ne "1") {                                                                                                                                                      
            Write-Error "Invalid choice '$choice'. Enter 1 or 2."                                                                                                                                           
            return                                                                                                                                                                                          
        }                                                                                                                                                                                                   
    }                                                                                                                                                                                                       
                                                                                                                                                                                                            
    $existingDocs = Get-ChildItem -LiteralPath $installBase -Directory -ErrorAction SilentlyContinue |                                                                                                      
        Where-Object { $_.Name -ieq "docs" } |                                                                                                                                                              
        Select-Object -First 1                                                                                                                                                                              
    $docsName  = if ($existingDocs) { $existingDocs.Name } else { "docs" }                                                                                                                                  
    $docsDir   = Join-Path $installBase $docsName                                                                                                                                                           
    $targetDir = Join-Path $docsDir "Coding-Workflow"                                                                                                                                                       
                                                                                                                                                                                                            
    if (-not (Test-Path -LiteralPath $targetDir)) {                                                                                                                                                         
        New-Item -ItemType Directory -Path $targetDir -Force | Out-Null                                                                                                                                     
    }                                                                                                                                                                                                       
                                                                                                                                                                                                            
    $baseUrl = "https://raw.githubusercontent.com/$Repo/$Branch"                                                                                                                                            
    $files   = @("AGENTS.md", "PROJECT-MAP.md", "LARGE-CHANGES.md", "HANDOFF.md")                                                                                                                           
                                                                                                                                                                                                            
    foreach ($file in $files) {                                                                                                                                                                             
        $destinationPath = Join-Path $targetDir $file                                                                                                                                                       
                                                                                                                                                                                                            
        if ((Test-Path -LiteralPath $destinationPath) -and -not $Force) {                                                                                                                                   
            Write-Host "Skipped file already exists: $file" -ForegroundColor Yellow                                                                                                                         
            continue                                                                                                                                                                                        
        }                                                                                                                                                                                                   
                                                                                                                                                                                                            
        $url = "$baseUrl/$file"                                                                                                                                                                             
        Invoke-WebRequest -Uri $url -OutFile $destinationPath -UseBasicParsing                                                                                                                              
        Write-Host "Downloaded: $file" -ForegroundColor Green                                                                                                                                               
    }                                                                                                                                                                                                       
                                                                                                                                                                                                            
    if ($selectedCsproj) {                                                                                                                                                                                  
        [xml]$projXml = Get-Content -LiteralPath $selectedCsproj.FullName -Raw                                                                                                                              
                                                                                                                                                                                                            
        if ($projXml.DocumentElement.HasAttribute("Sdk")) {                                                                                                                                                 
            Write-Host "SDK-style project detected ($($selectedCsproj.Name)); $docsName\Coding-Workflow appears automatically." -ForegroundColor Cyan                                                       
            return                                                                                                                                                                                          
        }                                                                                                                                                                                                   
                                                                                                                                                                                                            
        $ns    = $projXml.DocumentElement.NamespaceURI                                                                                                                                                      
        $nsMgr = New-Object System.Xml.XmlNamespaceManager($projXml.NameTable)                                                                                                                              
        if ($ns) {                                                                                                                                                                                          
            $nsMgr.AddNamespace("ms", $ns)                                                                                                                                                                  
        }                                                                                                                                                                                                   
                                                                                                                                                                                                            
        $existingItems = if ($ns) {                                                                                                                                                                         
            @($projXml.SelectNodes("//ms:None | //ms:Content", $nsMgr))                                                                                                                                     
        }                                                                                                                                                                                                   
        else {                                                                                                                                                                                              
            @($projXml.SelectNodes("//None | //Content"))                                                                                                                                                   
        }                                                                                                                                                                                                   
                                                                                                                                                                                                            
        $group = if ($ns) { $projXml.CreateElement("ItemGroup", $ns) } else { $projXml.CreateElement("ItemGroup") }                                                                                         
        $added = 0                                                                                                                                                                                          
                                                                                                                                                                                                            
        foreach ($file in $files) {                                                                                                                                                                         
            $rel    = "$docsName\Coding-Workflow\$file"                                                                                                                                                     
            $exists = $existingItems | Where-Object { $_.Include -ieq $rel }                                                                                                                                
                                                                                                                                                                                                            
            if (-not $exists) {                                                                                                                                                                             
                $node = if ($ns) { $projXml.CreateElement("None", $ns) } else { $projXml.CreateElement("None") }                                                                                            
                $node.SetAttribute("Include", $rel)                                                                                                                                                         
                $group.AppendChild($node) | Out-Null                                                                                                                                                        
                $added++                                                                                                                                                                                    
            }                                                                                                                                                                                               
        }                                                                                                                                                                                                   
                                                                                                                                                                                                            
        if ($added -gt 0) {                                                                                                                                                                                 
            $projXml.DocumentElement.AppendChild($group) | Out-Null                                                                                                                                         
            $projXml.Save($selectedCsproj.FullName)                                                                                                                                                         
            Write-Host "Added $added workflow file(s) to: $($selectedCsproj.Name)" -ForegroundColor Green                                                                                                   
        }                                                                                                                                                                                                   
        else {                                                                                                                                                                                              
            Write-Host "Skipped .csproj update (files already included in $($selectedCsproj.Name))." -ForegroundColor Yellow                                                                                
        }                                                                                                                                                                                                   
    }                                                                                                                                                                                                       
    else {                                                                                                                                                                                                  
        $slnxFiles = @(Get-ChildItem -LiteralPath $rootDir -Filter "*.slnx" -File)                                                                                                                          
        $slnFiles  = @(Get-ChildItem -LiteralPath $rootDir -Filter "*.sln" -File)                                                                                                                           
                                                                                                                                                                                                            
        if ($slnxFiles.Count -eq 1) {                                                                                                                                                                       
            $slnxPath   = $slnxFiles[0].FullName                                                                                                                                                            
            $slnxFolder = "/$docsName/Coding-Workflow/"                                                                                                                                                     
            [xml]$xml   = Get-Content -LiteralPath $slnxPath -Raw                                                                                                                                           
                                                                                                                                                                                                            
            $existingFolder = @($xml.SelectNodes("/Solution/Folder")) | Where-Object { $_.Name -ieq $slnxFolder }                                                                                           
            if ($existingFolder) {                                                                                                                                                                          
                Write-Host "Skipped .slnx update (already contains $slnxFolder)." -ForegroundColor Yellow                                                                                                   
                return                                                                                                                                                                                      
            }                                                                                                                                                                                               
                                                                                                                                                                                                            
            $folder = $xml.CreateElement("Folder")                                                                                                                                                          
            $folder.SetAttribute("Name", $slnxFolder)                                                                                                                                                       
            foreach ($file in $files) {                                                                                                                                                                     
                $fileNode = $xml.CreateElement("File")                                                                                                                                                      
                $fileNode.SetAttribute("Path", "$docsName/Coding-Workflow/$file")                                                                                                                           
                $folder.AppendChild($fileNode) | Out-Null                                                                                                                                                   
            }                                                                                                                                                                                               
            $xml.Solution.AppendChild($folder) | Out-Null                                                                                                                                                   
                                                                                                                                                                                                            
            $settings = New-Object System.Xml.XmlWriterSettings                                                                                                                                             
            $settings.Indent = $true                                                                                                                                                                        
            $settings.OmitXmlDeclaration = $true                                                                                                                                                            
            $writer = [System.Xml.XmlWriter]::Create($slnxPath, $settings)                                                                                                                                  
            try {                                                                                                                                                                                           
                $xml.Save($writer)                                                                                                                                                                          
            }                                                                                                                                                                                               
            finally {                                                                                                                                                                                       
                $writer.Dispose()                                                                                                                                                                           
            }                                                                                                                                                                                               
                                                                                                                                                                                                            
            Write-Host "Added $slnxFolder folder to: $($slnxFiles[0].Name)" -ForegroundColor Green                                                                                                          
        }                                                                                                                                                                                                   
        elseif ($slnFiles.Count -eq 1) {                                                                                                                                                                    
            $slnPath = $slnFiles[0].FullName                                                                                                                                                                
            $content = Get-Content -LiteralPath $slnPath -Raw                                                                                                                                               
                                                                                                                                                                                                            
            if ($content -match '"Coding-Workflow"') {                                                                                                                                                      
                Write-Host "Skipped .sln update (already contains Coding-Workflow)." -ForegroundColor Yellow                                                                                                
                return                                                                                                                                                                                      
            }                                                                                                                                                                                               
                                                                                                                                                                                                            
            $folderGuid  = [guid]::NewGuid().ToString("B").ToUpper()                                                                                                                                        
            $itemLines   = ($files | ForEach-Object { "`t`t$docsName\Coding-Workflow\$_ = $docsName\Coding-Workflow\$_" }) -join "`r`n"                                                                     
            $folderBlock = @(                                                                                                                                                                               
                "Project(`"{2150E333-8FDC-42A3-9474-1A3956D46DE8}`") = `"Coding-Workflow`", `"Coding-Workflow`", `"$folderGuid`""                                                                           
                "`tProjectSection(SolutionItems) = preProject"                                                                                                                                              
                $itemLines                                                                                                                                                                                  
                "`tEndProjectSection"                                                                                                                                                                       
                "EndProject"                                                                                                                                                                                
            ) -join "`r`n"                                                                                                                                                                                  
                                                                                                                                                                                                            
            $regex = [regex]::new('(?m)^Global\r?$')                                                                                                                                                        
            if ($regex.IsMatch($content)) {                                                                                                                                                                 
                $updated = $regex.Replace($content, "$folderBlock`r`nGlobal", 1)                                                                                                                            
                [System.IO.File]::WriteAllText($slnPath, $updated, (New-Object System.Text.UTF8Encoding($true)))                                                                                            
                Write-Host "Added Coding-Workflow folder to: $($slnFiles[0].Name)" -ForegroundColor Green                                                                                                   
            }                                                                                                                                                                                               
        }                                                                                                                                                                                                   
    }                                                                                                                                                                                                       